begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(21);
insert into public.clinics(id,name) values('a1000000-0000-4000-8000-000000000001','Synthetic Team A'),('a1000000-0000-4000-8000-000000000002','Synthetic Team B');
insert into auth.users(id) values('a2000000-0000-4000-8000-000000000001');
insert into public.profiles(user_id,display_name) values('a2000000-0000-4000-8000-000000000001','Alpha');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','manager',true);
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
select ok(not has_function_privilege('anon','public.team_roster(uuid)','EXECUTE'),'anonymous cannot execute');
set local role authenticated;
select is(jsonb_array_length(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'),1,'manager sees roster');
select is((public.team_roster('a1000000-0000-4000-8000-000000000001')->>'observed_at')::timestamptz,statement_timestamp(),'one database observation');
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000002')$$,'42501',null,'foreign clinic denied');
reset role;
update public.clinic_memberships set role='dentist' where user_id='a2000000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'),1,'dentist authorized');
update public.clinic_memberships set role='reception' where user_id='a2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'42501',null,'privileged reception denied');
update public.clinic_memberships set role='assistant' where user_id='a2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'42501',null,'privileged assistant denied');
update public.clinic_memberships set role='manager',active=false where user_id='a2000000-0000-4000-8000-000000000001';
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'42501',null,'inactive actor denied');
update public.clinic_memberships set active=true where user_id='a2000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'28000',null,'missing subject denied even privileged');
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','GET',true);
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'22023',null,'RPC GET denied');
select set_config('request.method','POST',true);
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','assistant',true),('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','dentist',true);
select is(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'->0->'roles','["assistant","dentist","manager"]'::jsonb,'roles canonical and unique');
select is((select count(*)::int from jsonb_object_keys(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'->0)),4,'minimal projection');
insert into auth.users(id) select ('a3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,100)n;
insert into public.clinic_memberships(clinic_id,user_id,role,active) select 'a1000000-0000-4000-8000-000000000001',id,'assistant',true from auth.users where id::text like 'a3000000-%';
insert into public.profiles(user_id,display_name) select id, 'Synthetic '||id::text from auth.users where id::text like 'a3000000-%' and id<>'a3000000-0000-4000-8000-000000000100';
set local role authenticated;
select throws_ok($$select public.team_roster('a1000000-0000-4000-8000-000000000001')$$,'PT503','Team roster unavailable','missing profile beyond limit fails complete roster');
reset role;
insert into public.profiles(user_id,display_name) values('a3000000-0000-4000-8000-000000000100','zzzz last');
select is(jsonb_array_length(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'),100,'101 distinct members capped at 100');
select is((public.team_roster('a1000000-0000-4000-8000-000000000001')->>'truncated')::boolean,true,'truncation explicit');
update public.clinic_memberships set active=false where user_id='a3000000-0000-4000-8000-000000000100';
select is((public.team_roster('a1000000-0000-4000-8000-000000000001')->>'truncated')::boolean,false,'100 distinct members complete despite extra roles');
update public.profiles set display_name='aLPHa' where user_id='a3000000-0000-4000-8000-000000000001';
select is(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'->0->>'user_id','a2000000-0000-4000-8000-000000000001','case-folded C order uses UUID tie break');
select is(public.team_roster('a1000000-0000-4000-8000-000000000001')->'members'->1->>'user_id','a3000000-0000-4000-8000-000000000001','equal case-folded name follows tie break');
select is((select provolatile::text from pg_proc where oid='public.team_roster(uuid)'::regprocedure),'s','stable statement snapshot');
select is((select count(*)::int from private.outbox_events where clinic_id='a1000000-0000-4000-8000-000000000001'),0,'read emits no outbox event');
select throws_ok($$insert into public.profiles(user_id,display_name) values('a2000000-0000-4000-8000-000000000001','Duplicate')$$,'23505',null,'duplicate profile impossible');
select * from finish();
rollback;
